+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "globalmenu.h"
+
+#include <QGuiApplication>
+
+#include <KLocalizedString>
+
+GlobalMenu::GlobalMenu(QObject *parent)
+    : QObject(parent)
+    , m_menu(std::make_unique<QMenu>())
+{
+    // The menu is shown by the Global Menu applet, which can't tell us when it opens it
+    connect(qGuiApp, &QGuiApplication::focusWindowChanged, this, [this](QWindow *window) {
+        if (m_model && window && window == m_window) {
+            m_model->updateActions();
+        }
+    });
+}
+
+GlobalMenu::~GlobalMenu() = default;
+
+FolderModel *GlobalMenu::model() const
+{
+    return m_model;
+}
+
+void GlobalMenu::setModel(FolderModel *model)
+{
+    if (m_model != model) {
+        m_model = model;
+        rebuild();
+        Q_EMIT modelChanged();
+    }
+}
+
+QMenu *GlobalMenu::viewMenu() const
+{
+    return m_viewMenu;
+}
+
+void GlobalMenu::setViewMenu(QMenu *menu)
+{
+    if (m_viewMenu != menu) {
+        m_viewMenu = menu;
+        rebuild();
+        Q_EMIT viewMenuChanged();
+    }
+}
+
+QQuickWindow *GlobalMenu::window() const
+{
+    return m_window;
+}
+
+void GlobalMenu::setWindow(QQuickWindow *window)
+{
+    if (m_window != window) {
+        m_window = window;
+        Q_EMIT windowChanged();
+    }
+}
+
+QAction *GlobalMenu::action() const
+{
+    return m_menu->menuAction();
+}
+
+void GlobalMenu::addMenu(const QString &title, const QList<QAction *> &actions)
+{
+    QMenu *menu = m_menu->addMenu(title);
+    for (QAction *action : actions) {
+        if (action) {
+            menu->addAction(action);
+        } else {
+            menu->addSeparator();
+        }
+    }
+}
+
+void GlobalMenu::rebuild()
+{
+    qDeleteAll(m_menu->findChildren<QMenu *>(Qt::FindDirectChildrenOnly));
+
+    if (!m_model) {
+        return;
+    }
+
+    addMenu(i18nc("@title:menu", "File"),
+            {m_model->action(QStringLiteral("newMenu")),
+             nullptr,
+             m_model->action(QStringLiteral("rename")),
+             m_model->action(QStringLiteral("trash")),
+             m_model->action(QStringLiteral("del")),
+             m_model->action(QStringLiteral("emptyTrash"))});
+    addMenu(i18nc("@title:menu", "Edit"),
+            {m_model->action(QStringLiteral("undo")),
+             nullptr,
+             m_model->action(QStringLiteral("cut")),
+             m_model->action(QStringLiteral("copy")),
+             m_model->action(QStringLiteral("paste"))});
+
+    QList<QAction *> viewActions;
+    if (m_viewMenu) {
+        viewActions = m_viewMenu->actions();
+        viewActions << nullptr;
+    }
+    viewActions << m_model->action(QStringLiteral("refresh"));
+    addMenu(i18nc("@title:menu", "View"), viewActions);
+}
