     connect(m_tasksModel, &TaskManager::TasksModel::screenGeometryChanged, this, &AppMenuModel::screenGeometryChanged);

+    connect(qGuiApp, &QGuiApplication::focusWindowChanged, this, &AppMenuModel::onFocusWindowChanged);
+
     connect(this, &AppMenuModel::modelNeedsUpdate, this, [this] {
         if (!m_updatePending) {
             m_updatePending = true;
@@ -68,6 +72,7 @@ AppMenuModel::AppMenuModel(QObject *parent)
         }
     });

+    onFocusWindowChanged(qGuiApp->focusWindow());
     onActiveWindowChanged();

     m_serviceWatcher->setConnection(QDBusConnection::sessionBus());
@@ -220,11 +225,58 @@ void AppMenuModel::onActiveWindowChanged()
     }

     const QModelIndex activeTaskIndex = m_tasksModel->activeTask();
+    if (!activeTaskIndex.isValid()) {
+        if (QMenu *menu = desktopMenu()) {
+            if (!m_showingDesktopMenu || m_menu != menu) {
+                updateApplicationMenu(QString(), QString());
+                m_showingDesktopMenu = true;
+                m_menu = menu;
+                setMenuAvailable(true);
+                setVisible(true);
+                Q_EMIT modelNeedsUpdate();
+            }
+            return;
+        }
+    }
+
+    if (m_showingDesktopMenu) {
+        m_showingDesktopMenu = false;
+        m_menu.clear();
+        setMenuAvailable(false);
+        setVisible(false);
+        Q_EMIT modelNeedsUpdate();
+    }
+
     const QString objectPath = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuObjectPath).toString();
     const QString serviceName = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuServiceName).toString();
     updateApplicationMenu(serviceName, objectPath);
 }

+void AppMenuModel::onFocusWindowChanged(QWindow *window)
+{
+    // The desktop is not a task, but it can provide a menu while it has focus
+    if (!window) {
+        m_focusedDesktop.clear();
+    } else if (auto view = qobject_cast<PlasmaQuick::ContainmentView *>(window);
+               view && view->containment() && view->containment()->containmentType() == Plasma::Containment::Desktop) {
+        m_focusedDesktop = view;
+        connect(view->containment(), &Plasma::Applet::internalActionsChanged, this, &AppMenuModel::onActiveWindowChanged, Qt::UniqueConnection);
+    } else {
+        return;
+    }
+    onActiveWindowChanged();
+}
+
+QMenu *AppMenuModel::desktopMenu() const
+{
+    if (!m_focusedDesktop || (!m_allScreens && m_focusedDesktop->geometry() != screenGeometry())) {
+        return nullptr;
+    }
+
+    QAction *action = m_focusedDesktop->containment()->internalAction(QStringLiteral("applicationMenu"));
+    return action ? action->menu() : nullptr;
+}
+
 QHash<int, QByteArray> AppMenuModel::roleNames() const
 {
     QHash<int, QByteArray> roleNames;
